body {
  font-family: system-ui, sans-serif;
  background: var(--bg-secondary);
  color: var(--text-primary);
  height: 100vh;
  display: flex;
  flex-direction: column;
  transition: background-color 0.15s ease, color 0.15s ease;
}
label {
  color: var(--text-primary);
}
#toolbar {
  background: var(--bg-elevated);
  border-bottom: 1px solid var(--border-primary);
  padding: 8px 16px;
  display: flex;
  gap: 16px;
  align-items: center;
  transition: background-color 0.15s ease, border-color 0.15s ease;
}
#toolbar .separator {
  color: var(--text-tertiary);
  margin: 0 -8px;
}
/* Editor toggle button */
#editor-toggle {
  background: var(--bg-secondary);
  border: 1px solid var(--border-primary);
  padding: 4px 12px;
  border-radius: 4px;
  cursor: pointer;
  font-size: 12px;
  transition: background-color 0.15s;
}
#editor-toggle:hover {
  background: var(--border-primary);
}
/* Divider between editor and canvas */
#divider:hover {
  background: var(--accent-primary);
}
#canvas-container {
  flex: 1;
  position: relative;
  overflow: hidden;
}
#pcb-canvas {
  position: absolute;
  top: 0;
  left: 0;
  touch-action: none;
}
#status {
  position: absolute;
  bottom: 8px;
  left: 8px;
  background: var(--status-bg);
  padding: 4px 8px;
  border-radius: 4px;
  font-size: 12px;
  display: flex;
  align-items: center;
  gap: 8px;
  transition: background-color 0.15s ease, color 0.15s ease;
}
#error-badge {
  background: var(--error);
  color: white;
  padding: 2px 8px;
  border-radius: 10px;
  font-size: 11px;
  cursor: pointer;
}
#error-badge:hover {
  filter: brightness(0.85);
}
#error-badge.hidden {
  display: none;
}
/* Error panel (VS Code style) */
#error-panel {
  position: absolute;
  bottom: 40px;
  left: 8px;
  width: 350px;
  max-height: 200px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-primary);
  border-radius: 4px;
  box-shadow: 0 2px 8px var(--shadow);
  overflow: hidden;
  transition: background-color 0.15s ease, border-color 0.15s ease;
}
#error-panel.hidden {
  display: none;
}
#error-panel-header {
  padding: 8px 12px;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-primary);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-weight: 500;
}
#error-panel-close {
  background: none;
  border: none;
  font-size: 18px;
  cursor: pointer;
  color: var(--text-secondary);
}
